<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api,ApiError,type Account} from './api'
const props=defineProps<{account:Account}>(),emit=defineEmits<{expired:[]}>()
const data=ref<any>(null),events=ref<any[]>([]),risks=ref<any[]>([]),history=ref<any[]>([]),details=ref<any[]>([]),error=ref(''),q=ref(''),term=ref(''),type=ref(''),objectId=ref(''),personId=ref(''),from=ref(''),to=ref('')
const eventPage=ref(1)
function evidence(s:any){try{return (typeof s==='string'?JSON.parse(s):s).flat().map((e:any)=>e.term+'：'+e.text).join('；')}catch{return ''}}
const drawer=ref(false),personDetail=ref<any>(null),riskDetail=ref<any>(null),eventId=ref<number>()
async function inspect(id:number,event?:number){await run(async()=>{const [person,risk]=await Promise.all([api<any>('/intake/people/'+id),api<any>('/intake/people/'+id+'/risk')]);personDetail.value=person;riskDetail.value=risk;eventId.value=event;drawer.value=true})}
const center=props.account.roles.includes('CENTER_ANALYST')
async function run(f:()=>Promise<void>){error.value='';try{await f()}catch(e){error.value=e instanceof Error?e.message:'请求失败';if(e instanceof ApiError&&e.status===401)emit('expired')}}
async function load(){const query='?q='+encodeURIComponent(q.value);data.value=await api('/insights/dashboard'+query);events.value=await api('/insights/events'+query+'&page='+eventPage.value+'&size=50');if(center)risks.value=await api('/insights/risks'+query)}
async function logs(){const p=new URLSearchParams({type:type.value,from:from.value,to:to.value});if(objectId.value)p.set('objectId',objectId.value);if(personId.value)p.set('personId',personId.value);history.value=await api<any[]>('/insights/history?'+p)}
onMounted(()=>run(load))
</script>
<template><main class="content"><h1>业务概况与追溯</h1><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-input v-model="q" aria-label="统计筛选" placeholder="姓名或事件描述"/><el-button @click="eventPage=1;run(load)">查询概况</el-button><template v-if="data"><p>原始上报：{{data.reports}} · 权限内有效事件：{{data.effectiveEvents}} · 待处置任务：{{data.tasks}} · 部门逾期：{{data.overdue}} · 中心待审：{{data.pending}} · 身份待审：{{data.pendingIdentity}} · 重复待审：{{data.pendingDuplicate}} · 修正待审：{{data.pendingChanges}}</p><p>上报按来源记录计数，有效事件去重；关键词按人员内规则命中的有效事件次数统计。</p><el-descriptions :column="1" border><el-descriptions-item v-for="key in ['categories','sources','departments']" :key="key" :label="({categories:'类型分布',sources:'来源分布',departments:'来源部门分布'} as any)[key]">{{data[key]}}</el-descriptions-item></el-descriptions><h2>热点关键词</h2><el-button v-for="(count,word) in data.keywords" :key="word" @click="term=String(word);run(async()=>{details=await api<any[]>('/insights/keyword?term='+encodeURIComponent(term)+'&q='+encodeURIComponent(q))})">{{word}}（{{count}}）</el-button><el-table :data="details"><el-table-column prop="personId" label="人员编号"/><el-table-column prop="eventId" label="事件编号"/><el-table-column label="详情"><template #default="{row}"><el-button @click="inspect(row.personId,row.eventId)">查看人员与事件</el-button></template></el-table-column><el-table-column label="命中依据"><template #default="{row}">{{evidence(row.evidence)}}</template></el-table-column></el-table></template><h2>筛选范围内导出</h2><p><a :href="'/api/insights/export?kind=events&q='+encodeURIComponent(q)">导出事件 CSV</a> · <a :href="'/api/insights/export?kind=statistics&q='+encodeURIComponent(q)">导出统计 CSV</a> · <a v-if="center" :href="'/api/insights/export?kind=risks&q='+encodeURIComponent(q)">导出风险 CSV</a></p><h2>事件明细</h2><el-table :data="events"><el-table-column prop="id" label="来源编号"/><el-table-column prop="eventId" label="有效事件编号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="description" label="描述"/><el-table-column prop="source" label="来源"/></el-table><el-pagination v-if="data" v-model:current-page="eventPage" :total="data.reports" :page-size="50" layout="total, prev, pager, next" @current-change="run(load)"/><h2 v-if="center">风险明细</h2><el-table v-if="center" :data="risks"><el-table-column prop="id" label="档案编号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="level" label="等级"/><el-table-column prop="effectiveCount" label="有效次数"/><el-table-column label="档案"><template #default="{row}"><el-button @click="inspect(row.id)">查看档案</el-button></template></el-table-column></el-table><h2>操作历史</h2><el-input v-model="type" placeholder="对象类型，可留空"/><el-input v-model="objectId" placeholder="对象编号，可留空"/><el-input v-model="personId" placeholder="人员编号，可留空"/><el-input v-model="from" placeholder="起始时间 2026-10-01T00:00:00"/><el-input v-model="to" placeholder="截止时间 2026-10-31T23:59:59"/><el-button @click="run(logs)">查询操作历史</el-button><el-table :data="history"><el-table-column type="expand"><template #default="{row}"><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{row}}</pre></template></el-table-column><el-table-column prop="target_type" label="对象"/><el-table-column prop="target_id" label="编号"/><el-table-column prop="created_at" label="时间"/><el-table-column prop="state" label="业务状态"/><el-table-column label="操作者"><template #default="{row}">{{row.actor_username||row.actor||row.requester}}</template></el-table-column><el-table-column label="原因/结果"><template #default="{row}">{{row.reason||row.content||row.result||row.state}}</template></el-table-column></el-table><el-drawer v-model="drawer" title="关联人员与有效事件" size="min(700px,100vw)"><template v-if="personDetail && riskDetail"><h2>{{personDetail.person.name}}</h2><p>档案 #{{personDetail.person.id}} · 电话 {{personDetail.person.phone}} · 身份证 {{personDetail.person.idCard||'未填写'}}</p><p>有效次数 {{riskDetail.effectiveCount}} · 最终风险 {{riskDetail.finalLevel}}</p><section v-for="e in riskDetail.events.filter((e:any)=>!eventId||e.id===eventId)" :key="e.id"><h3>有效事件 #{{e.id}} · {{e.eventTime}}</h3><p v-for="source in e.sources" :key="source.recordId">来源记录 #{{source.recordId}} · {{source.source}} · {{source.description}}</p></section></template></el-drawer></main></template>
